-- Seed : bibliothèque de base Muscu (ADR-005). Source : free-exercise-db (Unlicense), noms traduits en FR.
-- Copiée dans le compte (is_custom = false). Idempotent : id déterministe dérivé de l'id source.
-- Données sources : supabase/seed/exercises.json ; images : public/exercises/<id>/{0,1}.jpg.

insert into public.muscu_exercises (id, user_id, name, primary_group, secondary_groups, image_path, is_custom)
